from pathlib import Path
root=Path(__file__).resolve().parents[1];d=root/'dist'
app=(d/'app.js').read_text()+'''\nwindow.hunterQa={advance(){state.paused=false;for(let n=0;n<2450;n++){game.advanceGame(state,.025);if(state.settlement)save();if(game.resultReady(state))break;}save();updateHud();},fail(){if(state.phase==='playing'){state.paused=false;state.run.timeRemaining=0;game.advanceGame(state,.025);save();updateHud();}},inspect(){return {phase:state.phase,dungeon:state.run.dungeonId,reward:state.run.dungeonReward,profile:JSON.parse(game.encodeProfile(profile)),frame:document.querySelector('#game-shell').dataset};}};'''
(d/'qa-stage-c-app.js').write_text(app)
(d/'qa-stage-c-game.html').write_text((d/'index.html').read_text().replace('src="app.js?v=0.99.0"','src="qa-stage-c-app.js?v=0.99.0"'))
(d/'qa-stage-c.html').write_text('''<!doctype html><meta charset="utf-8"><title>Stage C QA</title><style>body{margin:0;background:#222;color:#eee;font:12px sans-serif}header{padding:6px;height:32px}iframe{display:block;margin:8px;border:0}button,select{padding:4px}pre{white-space:pre-wrap}</style><header><select id="size" aria-label="검증 크기"><option>667x375</option><option>740x360</option><option selected>844x390</option><option>932x430</option></select><button id="seed">검증 세이브</button><button id="advance">실제 전투 계산</button><button id="fail">시간초과 계산</button><button id="inspect">저장 결과</button></header><iframe id="game" title="던전 검증" width="844" height="390"></iframe><pre id="result"></pre><script type="module">
import * as g from './game-engine.js?v=0.99.0';const f=document.querySelector('#game'),key='beast-hunter:profile:v1';document.querySelector('#size').onchange=()=>{const [w,h]=document.querySelector('#size').value.split('x');f.width=w;f.height=h;};document.querySelector('#seed').onclick=()=>{const p=g.createProfile();p.level=35;p.gold=10000;p.forge={blade:8,armor:6,core:5};p.skillBook=g.restoreSkillBook(null,35);p.skills={edge:4,chain:3,guard:4,haste:3,magnet:3,drain:3};p.materials.skillPage=3;const s=g.createGame(p);g.saveBuild(s,0,'일반 사냥');localStorage.setItem(key,g.encodeProfile(p));f.src='qa-stage-c-game.html';};document.querySelector('#advance').onclick=()=>f.contentWindow.hunterQa.advance();document.querySelector('#fail').onclick=()=>f.contentWindow.hunterQa.fail();document.querySelector('#inspect').onclick=()=>document.querySelector('#result').textContent=JSON.stringify(f.contentWindow.hunterQa.inspect(),null,2);
</script>''')
